const MISSING_BULK_ASSESSMENT_MESSAGE = 'No document bulk assessment found';

type HttpErrorLike = {
  status?: number;
  message?: string;
  response?: { status?: number };
};

/**
 * The carbon API returns HTTP 404 with this message when the company has no
 * saved bulk assessment and no transaction rows to summarise. That is an empty
 * footprint, not a broken request.
 */
export function isMissingDocumentBulkAssessment(error: unknown): boolean {
  if (!error || typeof error !== 'object') {
    return false;
  }
  const httpError = error as HttpErrorLike;
  const status = httpError.status ?? httpError.response?.status;
  const message = typeof httpError.message === 'string' ? httpError.message : '';
  return status === 404 && message.includes(MISSING_BULK_ASSESSMENT_MESSAGE);
}
